uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float density : 0.5 .. 8.0 = 3.0;
uniform float amplitude : 0.0 .. 1.0 = 0.6;
uniform vec3 tint : color = 0.2, 0.6, 1.0;

state fixed ph;
state fixed k;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.2));
  k = fixed(density);
}

vec3 shade(Led led) {
  fixed u = fixed(led.uv.x);
  fixed v = fixed(led.uv.y);
  fixed d = sin(u * k + ph) * fixed(amplitude);
  return hsv2rgb(fract(v + d), fixed(1.0), fixed(1.0));
}
